const has=(p:Player,kind:string)=>p.table.some(c=>c.kind===kind);
export const ability=(p:Player)=>p.silenced?'none':p.copied??p.character;
export const abilities=(p:Player):string[]=>p.silenced?[]:p.copied?(p.copied==='greygory'?['greygory',...(p.copiedAbilities??[])]:[p.copied]):p.character==='greygory'?['greygory',...(p.abilities??[])]:[p.character];
