export const greenReady=(g:State,p:Player,c:Card)=>!!CARDS[c.kind].green&&(c.placed??g.turn)<g.turn&&tableWorks(g,p);
const immune=(g:State,target:string,c:Card)=>(hasAbility(g.players[target],'apache')||equipped(g.players[target],'calumet'))&&suit(g,c)==='D';
export const needsTarget=(p:Player,c:Card)=>isBang(p,c)||['bomb','arrow','squaw','duel','panic','cat','jail','tequila','bounty','snake','phantom','fanning','kniferevolver','trainrobbery','switch'].includes(c.kind)||['shoot','steal','discard'].includes(CARDS[c.kind].effect??'');
const note=(g:State,s:string)=>{g.log.push(s);if(g.log.length>100)g.log.shift();};
function take(g:State,n:number,shuffle:Shuffle,phaseOne=false){const out:Card[]=[];for(let i=0;i<n;i++){if(phaseOne&&g.event==='mine'&&g.discard.length){out.push(g.discard.pop()!);continue;}if(!g.deck.length&&g.discard.length){g.deck=shuffle(g.discard);g.discard=[];note(g,'Сброс перемешан в новую колоду.');}const c=g.deck.shift();if(c)out.push(c);}return out;}
function draw(g:State,id:string,n:number,shuffle:Shuffle){g.players[id].hand.push(...take(g,n,shuffle));}
function remove(cards:Card[],id?:string){const i=cards.findIndex(c=>c.id===id);requireThat(i>=0,'Выберите доступную карту.');return cards.splice(i,1)[0];}
function discard(g:State,p:Player,id?:string){const c=remove(p.hand,id);delete c.placed;g.discard.push(c);LG.recordFeat(g,{type:'discard',player:p.id,card:c,zone:'hand'});return c;}
export function distance(g:State,from:string,to:string){if(from===to)return 0;if(LG.legendActive(g,from,'rose'))return 1;if(g.armed?.tower&&from===g.active)return 1;const ids=alive(g),a=ids.indexOf(from),b=ids.indexOf(to);if(a<0||b<0)return Infinity;const p=g.players[from],q=g.players[to];return Math.max(1,(g.event==='ambush'?1:Math.min(Math.abs(a-b),ids.length-Math.abs(a-b)))+Number(activeCard(g,q,'mustang'))+Number(activeCard(g,q,'hideout'))+Number(hasAbility(q,'paul'))-Number(activeCard(g,p,'scope'))-Number(activeCard(g,p,'binocular'))-Number(hasAbility(p,'rose'))+Number(activeCard(g,p,'rail_lumber'))-Number(activeCard(g,p,'rail_observation'))+Number(activeCard(g,q,'rail_observation')));}
export function range(p:Player,g?:State){if(g&&!tableWorks(g,p))return 1;return CARDS[p.table.find(c=>CARDS[c.kind]?.range)?.kind??'']?.range??1;}
