function revealWildwest(g:State,shuffle:Shuffle){
 if(!g.wwsDeck?.length||g.wws==='wildwest')return;g.wws=g.wwsDeck.shift();g.wwsRemaining=g.wwsDeck.length;g.ladyChain=0;note(g,'Дикий Запад: '+WILDWEST[g.wws!].name+'. '+WILDWEST[g.wws!].text);
 const redeal=(ids:string[])=>{const roles=shuffle(ids.map(id=>g.players[id].role));ids.forEach((id,i)=>{g.players[id].role=roles[i];g.players[id].roleSecret=true;});};
 if(g.wws==='orchard')redeal(g.seats.filter(id=>!g.players[id].alive));
 if(g.wws==='helena'){const c=take(g,1,shuffle)[0];if(c){g.discard.push(c);note(g,'Общая проверка: '+rank(c.rank)+SUITS[suit(g,c)]+'.');if(['H','D'].includes(suit(g,c)))redeal(alive(g).filter(id=>g.players[id].role!=='sheriff'));}}
}
function finishTurn(g:State,p:Player,shuffle:Shuffle,offerFeats=false){if(offerFeats&&g.discarding&&p.hand.length<=handLimit(p)&&LG.availableFeats(g,p.id).some(f=>f.eligible))return;if(p.shadow){nextTurn(g,shuffle);return;}if(p.hand.length>handLimit(p)){g.discarding=true;note(g,p.name+': сбросьте лишние карты до '+handLimit(p)+'.');}else nextTurn(g,shuffle);}
function startTurn(g:State,id:string,shuffle:Shuffle,extra=false){armedReleaseSuppression(g);armedTurn(g);g.active=id;g.turn++;if(g.legends)lc(g,shuffle).startTurn();g.uncleUsed=false;g.handcuffSuit=undefined;g.goldpanUsed=0;g.raddieUsed=0;g.luzenaUsed=false;g.donChecked=false;g.flintUsed=false;g.lastBrown=undefined;g.repeatUsed=false;g.bangs=0;g.played=0;g.ladyUsed=false;g.docUsed=false;g.joseUsed=0;g.flowerUsed=false;g.ringerUsed=false;g.drawn=false;g.discarding=false;g.lawCard=undefined;g.extraTurn=extra;g.queue=[];
 if(!extra&&id===g.eventLeader)revealEvent(g,shuffle);
 const p=g.players[id];if(!p.alive&&g.wws==='orchard'){p.alive=true;p.hp=1;p.ghost=false;note(g,p.name+' возвращается с Кладбища с 1 жизнью.');}if(!p.alive&&g.event==='ghost'){p.alive=true;p.ghost=true;p.hp=0;note(g,p.name+' возвращается призраком.');}
 if(!p.alive&&g.event==='deadman'&&!g.deadmanUsed){p.alive=true;p.hp=2;g.deadmanUsed=true;draw(g,id,2,shuffle);note(g,p.name+' возвращается: 2 жизни и 2 карты.');}
 if(!p.alive&&g.expansions.includes('shadows')){p.alive=true;p.shadow=true;p.hp=0;if(p.role==='renegade'){let law=0,outlaw=0;for(const other of Object.values(g.players)){if(other.id===id||other.alive&&!other.shadow&&other.role!=='sheriff')continue;if(other.shadowTeam==='law'||!other.shadowTeam&&['sheriff','deputy'].includes(other.role!))law++;if(other.shadowTeam==='outlaw'||!other.shadowTeam&&other.role==='outlaw')outlaw++;}p.shadowTeam=law>outlaw?'law':'outlaw';}note(g,p.name+' возвращается теневым стрелком.');}
 if(g.train)tr(g,shuffle).startTurn();if(hasAbility(p,'greygory'))g.queue.push({kind:'greygory',player:id});g.queue.push({kind:'event-start',player:id},{kind:'upkeep',player:id});note(g,'Ход '+g.turn+': '+p.name+'.');
}
function nextTurn(g:State,shuffle:Shuffle){if(g.legends&&!g.legendTurn?.used.includes('turn-ended')){if(lc(g,shuffle).endTurn())return;g.legendTurn?.used.push('turn-ended');}
 const current=g.players[g.active];if(g.train){tr(g,shuffle).endTurn();if(tr(g,shuffle).endExtra()){startTurn(g,current.id,shuffle,true);return;}}if(g.goldExtra){g.goldExtra=false;if(current.shadow)leaveShadow(g,current);else if(!current.phantom&&!current.ghost)current.hp=current.maxHp;if(g.train?.expressTurn!==g.turn){startTurn(g,current.id,shuffle,true);return;}}
 if(hasAbility(current,'don')&&!g.donChecked&&!g.extraTurn&&!g.pendingAdvance&&current.alive&&!current.ghost){g.donChecked=true;check(g,current.id,'don',shuffle);return;}
 if(current.shadow)leaveShadow(g,current);
 if(g.event==='vendetta'&&!g.extraTurn&&g.players[g.active].alive&&!g.pendingAdvance){check(g,g.active,'vendetta',shuffle);return;}
 g.pendingAdvance=false;const old=g.players[g.active];if(old.ghost&&!old.phantom){old.ghost=false;eliminated(g,old,undefined,shuffle);if(g.phase==='finished')return;if(g.queue.length){g.pendingAdvance=true;return;}}
 const eligible=g.seats.filter(id=>g.players[id].alive||g.expansions.includes('shadows')||g.wws==='orchard'||g.event==='ghost'||g.event==='deadman'&&!g.deadmanUsed&&id===g.seats.filter(t=>!g.players[t].alive).sort((a,b)=>(g.players[a].diedAt??Infinity)-(g.players[b].diedAt??Infinity))[0]);
 const direction=g.event==='goldrush'?-1:1,index=g.seats.indexOf(g.active);let id=g.active;for(let step=1;step<=g.seats.length;step++){const candidate=g.seats[(index+direction*step+g.seats.length)%g.seats.length];if(eligible.includes(candidate)){if(g.players[candidate].skipTurns){g.players[candidate].skipTurns!--;note(g,g.players[candidate].name+' пропускает ход после обмена местами.');continue;}id=candidate;break;}}
 startTurn(g,id,shuffle);
}
function phaseCount(g:State,p:Player){return Math.max(0,-Number(!!g.legendTurn?.oregon)+(hasAbility(p,'pixie')?3:hasAbility(p,'bill')?1+p.maxHp-p.hp:p.ghost?3:2)+(g.event==='thirst'?-1:g.event==='train'?1:0)+Number(equipped(p,'pickaxe'))+(hasAbility(p,'tuco')&&!p.table.some(c=>CARDS[c.kind].blue)?2:0));}
function blackBonus(g:State,p:Player,cards:Card[],shuffle:Shuffle){if(hasAbility(p,'black')&&cards[1]){note(g,p.name+' показывает вторую карту: '+CARDS[cards[1].kind].name+' '+rank(cards[1].rank)+SUITS[suit(g,cards[1])]+'.');if(['H','D'].includes(suit(g,cards[1])))draw(g,p.id,1,shuffle);}}
function phaseCards(g:State,p:Player,cards:Card[]){if(hasAbility(p,'dutch')&&cards.length){g.queue.push({kind:'dutch',player:p.id,cards});gainGold(g,p,1);}else p.hand.push(...cards);if(g.event==='law'&&cards[1]){g.lawCard=cards[1];note(g,p.name+' показывает: '+CARDS[cards[1].kind].name+'.');}g.drawn=true;if(g.event==='ranch')g.queue.push({kind:'ranch',player:p.id});if(g.event==='handcuffs')g.queue.push({kind:'handcuffs',player:p.id});}

function check(g:State,id:string,kind:'legend-jour'|'bomb'|'julie'|'barrel'|'jail'|'dynamite'|'vendetta'|'snake'|'colorado'|'teren'|'don',shuffle:Shuffle,allowLucky=true){LG.recordFeat(g,{type:'check',player:id===g.active?id:g.active});const owner=allowLucky&&!['legend-jour','julie','colorado','teren','don'].includes(kind)?LG.legendLuckyOwner(g):undefined;g.queue.unshift({kind:owner?'legend-lucky':'check',player:owner??id,other:owner?id:undefined,luckyOwner:owner===g.active?owner:undefined,checkAbility:!allowLucky||['legend-jour','julie','colorado','teren','don'].includes(kind),check:kind,cards:take(g,owner?2:1+Number(hasAbility(g.players[id],'lucky')&&!LG.legendActive(g,id,'lucky'))+Number(equipped(g.players[id],'horseshoe')),shuffle)});}
function checkReceipt(g:State,player:string,card:Card,title:string,result:string){g.checkHistory=[...(g.checkHistory??[]),{id:g.checkSerial=(g.checkSerial??0)+1,player,card:{...card},title,result,effectiveSuit:suit(g,card)}].slice(-8);note(g,title+': '+result);}
function checked(g:State,q:Prompt,c:Card,shuffle:Shuffle,skipArmed=false){if(!skipArmed&&armedOfferReroll(g,q,c,ah(g,shuffle)))return;const effective=suit(g,c),heartCheck=effective==='H';const checkTitle=({barrel:'Бочка',jail:'Тюрьма',dynamite:'Динамит',snake:'Гремучая змея','legend-jour':'Журдонне',bomb:'Бомба',julie:'Джули Каттер',don:'Дон Белл',teren:'Терен Килл',vendetta:'Вендетта',colorado:'Колорадо Билл'} as Record<string,string>)[q.check!]??'Проверка';const result=q.check==='barrel'?(heartCheck?(g.queue[0]?.count??1)>1?'Бочка даёт одно Мимо! Нужна ещё защита.':'Бочка остановила выстрел. Урона нет.':'Не черва: Бочка не сработала. Нужна защита или принятие урона.'):q.check==='jail'?(heartCheck?'Черва: вы вышли из Тюрьмы и продолжаете ход.':'Не черва: Тюрьма заставляет пропустить ход.'):q.check==='dynamite'?(effective==='S'&&c.rank>=2&&c.rank<=9?'Пика от 2 до 9: взрыв, 3 урона.':'Взрыва нет. Динамит передаётся дальше.'):q.check==='snake'?(effective==='S'?'Пика: змея наносит 1 урон.':'Не пика: укуса нет, жизнь не потеряна.'):q.check==='colorado'?(effective==='S'?'Пика: выстрел нельзя отменить.':'Не пика: обычный выстрел, защита разрешена.'):q.check==='bomb'?(['H','D'].includes(effective)?'Красная масть: выберите, кому передать Бомбу.':'Чёрная масть: Бомба теряет 2 заряда; при исчерпании зарядов взрывается.'):q.check==='teren'?(effective!=='S'?'Не пика: спасение, 1 жизнь и карта из колоды.':'Пика: способность не спасла от смерти.'):q.check==='don'?(['H','D'].includes(effective)?'Красная масть: дополнительный ход.':'Дополнительного хода нет.'):q.check==='julie'?(['H','D'].includes(effective)&&g.players[q.player].alive&&!!q.source&&g.players[q.source]?.alive?'Красная масть: ответный выстрел в нападавшего.':'Ответного выстрела нет: нужна красная масть и живые участники.'):q.check==='vendetta'?(heartCheck?'Черва: дополнительный ход.':'Дополнительного хода нет.'):q.check==='legend-jour'?(LG.legendJourdonnaisSuccess(c.rank)?'Проверка успешна: атака отменена.':'Защита не сработала; нужно ответить на атаку.'):'Проверка завершена.';checkReceipt(g,q.player,c,checkTitle,result);if(q.check==='legend-jour'){g.discard.push(...q.cards??[]);if(LG.legendJourdonnaisSuccess(c.rank))g.queue.shift();return;}const p=g.players[q.player],heart=suit(g,c)==='H';reserveCheckCards(g,p.id,q.cards!,q.luckyOwner?{player:q.luckyOwner,card:c.id}:undefined);note(g,`${p.name}: проверка ${q.check==='julie'?'Джули Каттер':q.check==='don'?'Дон Белл':q.check==='teren'?'Терен Килл':q.check==='vendetta'?'Вендетта':q.check==='colorado'?'Колорадо Билл':CARDS[q.check!].name} — ${rank(c.rank)}${SUITS[c.suit]}.`);
 if(q.check==='bomb'){armedBombCheck(g,p,c,ah(g,shuffle));return;}if(q.check==='julie'){if(p.alive&&q.source&&g.players[q.source]?.alive&&['H','D'].includes(suit(g,c)))g.queue.unshift(shot(g,q.source,p.id));return;}
 if(q.check==='don'){if(['H','D'].includes(suit(g,c))){if(p.shadow)leaveShadow(g,p);startTurn(g,p.id,shuffle,true);}else nextTurn(g,shuffle);return;}
 if(q.check==='teren'){if(suit(g,c)!=='S'){p.hp=1;draw(g,p.id,1,shuffle);note(g,p.name+' остаётся в игре: 1 жизнь.');}else deathCleanup(g,q,shuffle);return;}
 if(q.check==='colorado'){if(suit(g,c)==='S'&&g.queue[0]?.kind==='shot'){g.queue[0].unavoidable=true;g.queue[0].barrels=0;}return;}if(q.check==='snake'){if(suit(g,c)==='S')damage(g,p.id,undefined,1,shuffle);return;}
 if(q.check==='vendetta'){if(heart)startTurn(g,p.id,shuffle,true);else {g.pendingAdvance=true;nextTurn(g,shuffle);}return;}
 if(q.check==='barrel'){const s=g.queue[0];if(heart&&s?.kind==='shot'){s.count!--;if(s.count!<=0){g.queue.shift();armedCanceled(g,s,ah(g,shuffle));}}}
 if(q.check==='jail'){g.discard.push(remove(p.table,p.table.find(c=>c.kind==='jail')!.id));if(!heart){note(g,`${p.name} пропускает ход из-за Тюрьмы.`);g.queue=[];g.donChecked=true;nextTurn(g,shuffle);}}
 if(q.check==='dynamite'){const dynamite=remove(p.table,p.table.find(c=>c.kind==='dynamite')!.id);if(suit(g,c)==='S'&&c.rank>=2&&c.rank<=9){g.discard.push(dynamite);damage(g,p.id,undefined,3,shuffle);}else {const id=around(g,p.id).find(id=>!has(g.players[id],'dynamite'));if(id)g.players[id].table.push(dynamite);else p.table.push(dynamite);note(g,`Динамит передан: ${g.players[id??p.id].name}.`);}}
}
function stabilize(g:State,shuffle:Shuffle){armedCleanup(g);for(let guard=0;guard<120&&g.phase==='play';guard++){
 if(g.train){normalizeTrain(g,shuffle);if(g.phase!=='play')break;if(tr(g,shuffle).stabilize())continue;}
 const vanished=alive(g).find(id=>g.players[id].phantom&&!has(g.players[id],'phantom'));if(vanished){eliminated(g,g.players[vanished],undefined,shuffle);continue;}
 if(g.armed?.suppressed&&!g.queue.some(q=>q.kind==='shot'&&q.armed?.weapon==='bigfifty'||['dying','eliminate','save','save-reward','check'].includes(q.kind)))armedReleaseSuppression(g);
 settleCheckCards(g);const q=g.queue[0];
 if(q?.kind==='armed-rust'){g.queue.shift();armedRustTarget(g,q.player,q.source!,ah(g,shuffle));continue;}
 if(q?.kind==='armed-julie'){g.queue.shift();if(g.players[q.player].alive){check(g,q.player,'julie',shuffle);g.queue[0].source=q.source;}continue;}
 if(q?.kind==='armed-discard'&&!g.players[q.player].hand.length){g.queue.shift();continue;}
 if(q?.kind==='force'){const p=g.players[q.player],valid=p.hand.some(c=>c.kind===q.original?.kind&&(!CARDS[c.kind].cost||p.hand.some(x=>x.id!==c.id&&(c.kind!=='aim'||isBang(p,x))))&&(CARDS[c.kind].green||!needsTarget(p,c)||targets(g,p.id,c).includes(q.payload?.target??'')));if(!valid){g.queue.shift();note(g,p.name+': приказ невозможно выполнить с этой целью или оплатой.');continue;}}
 if(q?.kind==='finish-turn'){g.queue.shift();if(g.players[q.player].alive)finishTurn(g,g.players[q.player],shuffle,true);else nextTurn(g,shuffle);continue;}
 if(q?.kind==='transfer'){g.queue.shift();transfer(g,q,shuffle);continue;}
 if(q?.kind==='resume'){g.queue.shift();if(!g.players[q.player].alive)continue;g.henryPaid=q.other;const r=act(g,q.player,q.payload!,shuffle);requireThat(!r.error,r.error??'');Object.assign(g,r.state);delete g.undo;delete g.henryPaid;continue;}
 if(q?.kind==='poker-pick'&&!q.handled){q.handled=true;const cards=q.pool??[];if(cards.some(c=>c.rank===14)||!cards.length){g.discard.push(...cards);g.queue.shift();continue;}q.cards=cards;delete q.pool;}
 if(q?.kind==='save-reward'){const v=g.players[q.other!];if(!v.alive||v.hp<=0||!v.hand.length){g.queue.shift();continue;}if(!q.handled&&hasAbility(v,'henry')){q.handled=true;g.queue.unshift(shot(g,q.player,v.id));continue;}q.revealed=[...v.hand];}
 if(q?.kind==='jim'&&(g.players[q.player].phantom||g.players[q.player].hp>=g.players[q.player].maxHp||!g.players[q.player].hand.length)){g.queue.shift();continue;}
 if(q?.kind==='shotgun'&&!g.players[q.player].hand.length){g.queue.shift();continue;}
 if(q?.kind==='poker'&&!g.players[q.player].hand.length){g.queue.shift();continue;}
 if(q?.kind==='tornado'&&!g.players[q.player].hand.length){g.queue.shift();draw(g,q.player,2,shuffle);continue;}
 if(q?.kind==='shot'&&q.unavoidable){g.queue.shift();damage(g,q.player,q.source,q.damage??1,shuffle,!!q.bang);continue;}

 if(q?.kind==='event-start'){g.queue.shift();const p=g.players[q.player];if(!p.alive)continue;if(g.wws==='darling'){const n=p.hand.length;g.discard.push(...p.hand);p.hand=[];draw(g,p.id,n,shuffle);note(g,p.name+' меняет всю руку: '+n+' карт.');}if(g.event==='highnoon')damage(g,p.id,undefined,1,shuffle);if(g.event==='fistful')g.queue.unshift(...p.hand.map(()=>shot(g,p.id,undefined)));if(g.event==='identity'&&p.spareCharacter)g.queue.unshift({kind:'identity',player:p.id});if(g.event==='blood'&&p.hp>1)g.queue.unshift({kind:'blood',player:p.id});continue;}
 if(!q&&g.pendingAdvance){nextTurn(g,shuffle);continue;}
 if(q?.kind==='store'&&q.cards?.length===0){g.queue.shift();if(g.queue[0]?.kind==='store')g.queue[0].cards=[];continue;}
 if((q?.kind==='dying'||q?.kind==='eliminate')&&g.players[q.player].hp>0){g.queue.shift();continue;}
 if(q&& !g.players[q.player].alive){g.discard.push(...(q.cards??[]),...(q.pool??[]));g.queue.shift();continue;}
 if(q?.kind==='upkeep'){const p=g.players[q.player];if(activeCard(g,p,'dynamite')){q.kind='draw';q.after='upkeep';check(g,p.id,'dynamite',shuffle);continue;}q.kind='draw';q.after='upkeep';continue;}
 if(q?.kind==='draw'&&q.after==='upkeep'){q.after='snake';const p=g.players[q.player];if(activeCard(g,p,'jail')){if(g.legends)g.queue.unshift({kind:'legend-jail',player:p.id});else check(g,p.id,'jail',shuffle);}continue;} if(q?.kind==='draw'&&q.after==='snake'){q.after='bomb';const p=g.players[q.player];if(activeCard(g,p,'snake')){check(g,p.id,'snake',shuffle);continue;}}if(q?.kind==='draw'&&q.after==='bomb'){delete q.after;const p=g.players[q.player];if(activeCard(g,p,'bomb')){check(g,p.id,'bomb',shuffle);continue;}}
 if(q?.kind==='draw'&&!q.after&&g.train&&tr(g,shuffle).beforeDraw())continue;
 if(q?.kind==='draw'&&!q.after&&!q.handled){const p=g.players[q.player];q.handled=true;if(hasAbility(p,'youl')){const count=p.hand.length;g.queue.unshift(...around(g,p.id).filter(id=>id!==p.id&&g.players[id].hand.length>count).map(player=>({kind:'youl' as const,player,other:p.id})));}if(g.queue[0]!==q)continue;}
 if(q?.kind==='youl'&&(!g.players[q.other!].alive||!g.players[q.player].hand.length)){g.queue.shift();continue;}
 if(q?.kind==='draw'&&!q.after&&!g.players[q.player].silenced&&g.players[q.player].character==='vera'&&g.players[q.player].copiedTurn!==g.turn){g.queue.unshift({kind:'vera',player:q.player});continue;}
 if(q?.kind==='kit'&&!(q.kept?.length)&&(q.count===0||q.count!>=(q.cards?.length??0))){g.queue.shift();const cards=[...(q.prefix??[]),...(q.count===0?[]:q.cards??[])];if(q.count===0)g.deck.unshift(...q.cards??[]);phaseCards(g,g.players[q.player],cards);blackBonus(g,g.players[q.player],cards,shuffle);continue;}
 if(q?.kind==='check'&&q.cards?.length===1){g.queue.shift();checked(g,q,q.cards[0],shuffle);continue;}
 if(q?.kind==='check'&&!q.cards?.length){throw Error('Недостаточно карт для проверки.');}
 if(q?.kind==='dying'){const p=g.players[q.player],beers=beerWorks(g)?p.hand.filter(c=>c.kind==='beer').length:0,sid=hasAbility(p,'sid')?Math.floor((p.hand.length-beers)/2):0;if(p.hp+beers*(hasAbility(p,'joe')?2:1)+sid+(equipped(p,'rucksack')?Math.floor((p.gold??0)/2):0)<=0){g.queue.shift();attemptDeath(g,q,shuffle);continue;}}
 if(!g.queue.some(q=>q.kind==='duel')&&!g.queue.some(q=>q.kind==='dying'||q.kind==='eliminate')){for(const [id,n] of Object.entries(g.mollyBank??{}))if(g.players[id].alive)draw(g,id,n,shuffle);g.mollyBank={};for(const id of alive(g)){const p=g.players[id];if(LG.legendActive(g,id,'suzy'))LG.legendEmptyHand(g,id,lh(g,shuffle));else if(hasAbility(p,'suzy')&&!p.hand.length)draw(g,id,1,shuffle);}}
 if(!g.queue.length&&!g.players[g.active].alive){nextTurn(g,shuffle);continue;}
 break;
 }settleCheckCards(g);g.deckCount=g.deck.length;for(const p of Object.values(g.players))p.handCount=p.hand.length;
}
export function setup(n:number,shuffle:Shuffle,expansions:string[]=[]):State{requireThat(expansions.every(x=>x in EXPANSIONS),'Неизвестное дополнение.');requireThat(Number.isInteger(n)&&n>=(expansions.includes('dodge')?3:4)&&n<=(expansions.includes('legends')?7:expansions.includes('dodge')?8:7),'База: 4–7 игроков; Додж-Сити: 3–8.');const seats=Array.from({length:n},(_,i)=>String(i));return {phase:'lobby',players:Object.fromEntries(seats.map(id=>[id,{id,name:`Игрок ${+id+1}`,role:null,character:'',hp:0,maxHp:0,alive:true,hand:[],table:[],handCount:0}])),seats,active:'0',turn:0,deck:[],deckCount:0,discard:[],queue:[],bangs:0,drawn:false,discarding:false,ready:{},errors:{},log:['Собираемся в салуне.'],winners:[],winningRole:'',manual:false,revision:0,expansions:[...new Set(expansions)],deathSerial:0};}
