function gainGold(g:State,p:Player,n:number){if(!n)return;p.gold=(p.gold??0)+n;note(g,p.name+': +'+n+' самородок.');}
function spendGold(p:Player,n:number){requireThat((p.gold??0)>=n,'Недостаточно самородков.');p.gold=(p.gold??0)-n;}
function dropEquipment(g:State,p:Player){g.equipmentDiscard??=[];g.equipmentDiscard.push(...p.equipment??[]);p.equipment=[];}
