function beerReward(g:State,shuffle:Shuffle){for(const id of alive(g))if(hasAbility(g.players[id],'yto'))draw(g,id,1,shuffle);}
function recover(p:Player,n:number){if(!p.shadow&&!p.ghost&&!p.phantom)p.hp=Math.min(p.maxHp,p.hp+n);}
